With an amazing amount of assistance from Yihui I have been very<br>successful in customizing knitr to make good use of the listings<br>package and to automatically create figure environments when a<br>caption= parameter is specified inside &lt;&lt;&gt;&gt;=.  I have slightly updated<br>the Sweavel LaTeX style file at <a href="http://biostat.mc.vanderbilt.edu/wiki/pub/Main/SweaveTemplate/Sweavel.sty" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://biostat.mc.vanderbilt.edu/wiki/pub/Main/SweaveTemplate/Sweavel.sty&amp;source=gmail&amp;ust=1792356616992000&amp;usg=AOvVaw2KG7acbZZi4zd-3iWoredb">http://biostat.mc.vanderbilt.edu/wiki/pub/Main/SweaveTemplate/Sweavel.sty</a>,<br>and I use the following knitr hooks/customizations:<br><br># All this goes into file setup.r<br>spar &lt;- function(mar=if(!axes)<br>                 c(2.25+bot-.45*multi,1.5+left,.5+top+.25*multi,.5+rt)<br>else<br>                 c(3.25+bot-.45*multi,3.5+left,.5+top+.25*multi,.<br>5+rt),<br>                 lwd = if(multi)1 else 1.75,<br>                 mgp = if(!axes) mgp=c(.75, .1, 0) else<br>                       if(multi) c(1.5, .365, 0) else c(2.4-.4, 0.475,<br>0),<br>                 tcl = if(multi)-0.25 else -0.4,<br>                 bot=0, left=0, top=0, rt=0, ps=if(multi) 14 else 10,<br>                 mfrow=NULL, axes=TRUE, ...)<br>  {<br>    multi &lt;- length(mfrow) &gt; 0<br>    par(mar=mar, lwd=lwd, mgp=mgp, tcl=tcl, ps=ps, ...)<br>    if(multi) par(mfrow=mfrow)<br>  }<br><br>knit_hooks$set(chunk = function(x, options) x) # do not wrap output in<br>kframe<br>## for those who read source code here: I cannot use echo=TRUE here<br>because<br>## the code  egin{lstlistings} and \end{lstlistings} will confuse the<br>## listings package and cause LaTeX errors<br><br>hook_lst_bf = function(x, options)<br>  paste(&#39;\begin{lstlisting}[basicstyle={\bfseries}]
&#39;, x,<br>        &#39;\end{lstlisting}
&#39;, sep = &#39;&#39;)<br>## Scode and Soutput are defined in Sweavel.sty using listings<br><br>unlink(&#39;messages.txt&#39;) # Start fresh with each run<br>hook_log = function(x, options) cat(x, file=&#39;messages.txt&#39;,<br>append=TRUE)<br><br>knit_hooks$set(source = function(x, options)<br>               paste(&#39;\begin{Scode}
&#39;, x, &#39;\end{Scode}
&#39;, sep=&#39;&#39;),<br>               output = function(x, options)<br>               paste(&#39;\begin{Soutput}
&#39;, x, &#39;\end{Soutput}
&#39;,<br>sep=&#39;&#39;),<br>               warning = hook_log, message = hook_log, error =<br>hook_lst_bf)<br>set_header(highlight = &#39;&#39;)<br><br>knit_hooks$set(plot=function (x, options) {<br>  if (!options$include)<br>    return(&quot;&quot;)<br>  ## Begin FH<br>  cap &lt;- options$caption<br>  bfig &lt;- efig &lt;- &#39;&#39;<br>  if(length(cap)) {<br>    if(<a href="http://is.na" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://is.na&amp;source=gmail&amp;ust=1792356616992000&amp;usg=AOvVaw11iPlvkheVAH1oezFv8sdK">is.na</a>(cap)) cap &lt;- &#39;&#39;<br>    lp &lt;- options$label.prefix<br>    lab &lt;- paste(lp, options$label, sep=&#39;&#39;)<br>    bfig &lt;- sprintf(&#39;\begin{figure}\label{%s}
&#39;, lab)<br>    scap &lt;- options$scaption<br>    scap &lt;- if(!length(scap) || <a href="http://is.na" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://is.na&amp;source=gmail&amp;ust=1792356616992000&amp;usg=AOvVaw11iPlvkheVAH1oezFv8sdK">is.na</a>(scap)) &#39;&#39; else<br>     paste(&#39;[&#39;, scap, &#39;]&#39;, sep=&#39;&#39;)<br>    efig &lt;- sprintf(&#39;\caption%s{\smaller %s}
\end{figure}
&#39;,<br>scap, cap)<br>  } # End FH<br>  rw = options$resize.width<br>  rh = options$resize.height<br>  resize1 = resize2 = &quot;&quot;<br>  if (!is.null(rw) || !is.null(rh)) {<br>    resize1 = sprintf(&quot;\resizebox{%s}{%s}{&quot;, ifelse(is.null(rw),<br>      &quot;!&quot;, rw), ifelse(is.null(rh), &quot;!&quot;, rh))<br>    resize2 = &quot;} &quot;<br>  }<br>  tikz &lt;- FALSE # FH<br>  a = options$fig.align<br>  fig.cur = options$fig.cur<br>  fig.num = options$fig.num<br>  if (is.null(fig.cur))<br>    fig.cur = 0L<br>  animate = options$fig.show == &quot;animate&quot;<br>  if (!tikz &amp;&amp; animate &amp;&amp; fig.cur &lt; fig.num)<br>    return(&quot;&quot;)<br>  align1 = switch(a, left = &quot;

&quot;, center = &quot;

\centering{}&quot;,<br>    right = &quot;

\hfill{}&quot;, &quot;&quot;)<br>  align2 = switch(a, left = &quot;\hfill{}

&quot;, center = &quot;

&quot;,<br>    right = &quot;

&quot;, &quot;&quot;)<br>  hold = options$fig.show == &quot;hold&quot;<br>  if (hold &amp;&amp; fig.cur &gt; 1L)<br>    align1 = &quot;&quot;<br>  if (hold &amp;&amp; fig.cur &gt; 0L &amp;&amp; fig.cur &lt; fig.num)<br>    align2 = &quot;&quot;<br>  size = paste(c(sprintf(&quot;width=%s&quot;, options$out.width),<br>sprintf(&quot;height=%s&quot;,<br>    options$out.height)), collapse = &quot;,&quot;)<br>  paste(bfig, align1, resize1, if (tikz) {   # FH added bfig,<br>    sprintf(&quot;\input{%s.tikz}&quot;, x[1])<br>  }<br>  else if (animate) {<br>    aniopts = options$aniopts<br>    aniopts = if (<a href="http://is.na" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://is.na&amp;source=gmail&amp;ust=1792356616992000&amp;usg=AOvVaw11iPlvkheVAH1oezFv8sdK">is.na</a>(aniopts))<br>      NULL<br>    else gsub(&quot;;&quot;, &quot;,&quot;, aniopts)<br>    if (nzchar(size))<br>      size = paste(size, sprintf(&quot;%s&quot;, aniopts), sep = &quot;,&quot;)<br>    if (nzchar(size))<br>      size = sprintf(&quot;[%s]&quot;, size)<br>    sprintf(&quot;\animategraphics%s{%s}{%s}{%s}{%s}&quot;, size,<br>            1/options$interval, sub(str_c(fig.num, &quot;$&quot;), &quot;&quot;,<br>                                    x[1]), 1L, fig.num)<br>  }<br>  else {<br>    if (nzchar(size))<br>      size = sprintf(&quot;[%s]&quot;, size)<br>    sprintf(&quot;\includegraphics%s{%s} &quot;, size, x[1])<br>  }, resize2, align2, efig, sep = &quot;&quot;)  # FH added efig,<br>})<br><br>knit_hooks$set(par=function(before, options, envir)<br>               if(before &amp;&amp; options$fig.show != &#39;none&#39;)<br>               {<br>                 p &lt;-<br>c(&#39;bty&#39;,&#39;mfrow&#39;,&#39;ps&#39;,&#39;bot&#39;,&#39;top&#39;,&#39;left&#39;,&#39;rt&#39;,&#39;lwd&#39;,<br>                        &#39;mgp&#39;,&#39;tcl&#39;, &#39;axes&#39;)<br>                 pars &lt;- opts_current$get(p)<br>                 pars &lt;- pars[!<a href="http://is.na" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://is.na&amp;source=gmail&amp;ust=1792356616992000&amp;usg=AOvVaw11iPlvkheVAH1oezFv8sdK">is.na</a>(names(pars))]<br>                 if(length(pars)) do.call(&#39;spar&#39;, pars) else spar()<br>               })<br><br>opts_knit$set(eval.opts = c(&#39;eval&#39;, &#39;echo&#39;, &#39;caption&#39;, &#39;scaption&#39;,<br>                &#39;mfrow&#39;, &#39;mgp&#39;, &#39;tcl&#39;))<br>## allows symbolic captions, mfrow, etc., short captions for table of<br>figures<br>## see <a href="http://yihui.name/knitr/options#package_options" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://yihui.name/knitr/options%23package_options&amp;source=gmail&amp;ust=1792356616992000&amp;usg=AOvVaw19fTkQMf_G7gw6RinJqyoz">http://yihui.name/knitr/options#package_options</a><br>## Allow symbolic mfrom, mgp, etc. because user may specify e.g.<br>c(1,2)<br>options(replace.assign=TRUE)<br><br>I don&#39;t put warnings in the report output but rather to a separate<br>file messages.txt<br><br>In knit_hooks$set(plot=function ....) see lines marked with FH to see<br>what I changed over what is provided with knitr.<br><br>Then in my individual documents I use:<br><br><br>&lt;&lt;echo=FALSE&gt;&gt;=<br>source(&#39;../setup.r&#39;)<br>@<br><br>\SweaveOpts{highlight=FALSE, fig.path=PREFIX-, fig.align=center,<br>fig.width=4, fig.height=3, fig.show=hold, comment=NA,<br>label.prefix=fig:gen-, par=TRUE}<br><br>. . .<br>&lt;&lt;rcscomp,mfrow=c(1\,2),fig.height=4,fig.width=6,caption=&quot;Restricted<br>cubic spline component variables for $k = 5$ and knots at $X = .05\, .<br>275\, .5\, .725$\, and $.95$. The left panel is a $y$--magnification<br>of the right panel.  Fitted functions such as those in Figure \<br>ef{fig:gen-rcsex} will be linear combinations of these basis<br>functions as long as knots are at the same locations used<br>here.&quot;,scaption=&quot;Restricted cubic spline component variables for 5<br>knots&quot;&gt;&gt;=<br>. . .<br>@<br><br>&lt;&lt;rcsex,fig.height=6,fig.width=7,bot=2,mfrow=c(2\,<br>2),ps=13,caption=&quot;Some typical restricted cubic spline functions for<br>$k = 3\, 4\, 5\, 6$.  The $y$--axis is $X\beta$.  Arrows indicate<br>knots. These curves were derived by randomly choosing values of $\beta<br>$ subject to standard deviations of fitted functions being<br>normalized.&quot;,scaption=&quot;Some typical restricted cubic spline<br>functions&quot;&gt;&gt;=<br>. . .<br>@<br><br>You can also stuff captions into R variables in earlier chunks then<br>call out the caption with caption=variable name in a later chunk.<br><br>I&#39;m very pleased with how this is working and plan to re-do my book<br>using this approach.<br><br>Thanks to Yihui and others who have helped so much.  If any of this<br>becomes built-in to knitr I&#39;ll have even less work to do next time.<br><br>Frank<br><br>
